var ENT=[["TCP/IP", "The internet's packet protocols."], ["HTTP/3 over QUIC", "Low-latency web transport."], ["CDNs", "Caching bytes near users worldwide."], ["Wireshark", "Packet-level network truth."], ["DNS", "The distributed phone book resolving names to addresses globally."], ["WebSockets", "Full-duplex browser channels for chat, games and live dashboards."], ["MQTT", "Lightweight pub-sub messaging for IoT over flaky links."]];
